import AbstractProvider, { ProviderParams, EndpointArgument, ParseArgument, ProviderOptions, SearchResult, LatLng } from './provider';
export type RequestResult = RawResult[];
export interface RawResult {
    place_id: string;
    licence: string;
    osm_type: string;
    osm_id: number;
    boundingbox: [string, string, string, string];
    lat: string;
    lon: string;
    display_name: string;
    class: string;
    type: string;
    importance: number;
    icon?: string;
}
export type OpenStreetMapProviderOptions = {
    searchUrl?: string;
    reverseUrl?: string;
} & ProviderOptions;
export default class CivilDefenseMapProvider extends AbstractProvider<RawResult[], RawResult> {
    searchUrl: string;
    reverseUrl: string;
    constructor(options?: OpenStreetMapProviderOptions);
    endpoint({ query, type }: EndpointArgument): string;
    reverseParams({ lat, lng }: LatLng): ProviderParams;
    parse(response: ParseArgument<RequestResult>): SearchResult<RawResult>[];
}
